  getGetAuthSessionQueryKey, getGetDashboardChartsQueryKey, getGetDashboardStatsQueryKey, getGetUserQueryKey,
  getGetProfileQueryKey, getListAlertsQueryKey, getListAuditLogsQueryKey, getListPermissionsQueryKey,
  getListRolesQueryKey, getListSecurityEventsQueryKey, getListSessionsQueryKey, getListUsersQueryKey,
  getHealthCheckQueryKey, getExportAuditLogsQueryKey, useAssignRolePermissions, useCreateRole,
  useCreateUser, useDeleteRole, useDeleteUser, useExportAuditLogs, useGetAuthSession, useGetUser,
  useGetDashboardCharts, useGetDashboardStats, useGetProfile, useHealthCheck, useListAlerts,
  useListAuditLogs, useListPermissions, useListRoles, useListSecurityEvents, useListSessions,
