import NotFound from '@/pages/not-found';

const queryClient = new QueryClient();
const navItems = [
  { href: '/dashboard', label: 'Overview', icon: Gauge },
  { href: '/users', label: 'Users', icon: UsersRound },
  { href: '/roles', label: 'Roles', icon: KeyRound },
  { href: '/permissions', label: 'Permissions', icon: FileKey2 },
  { href: '/security', label: 'Security events', icon: Shield },
  { href: '/alerts', label: 'Alert queue', icon: AlertTriangle },
  { href: '/audit', label: 'Audit trail', icon: ClipboardList },
];

const fmtDate = (value?: string | null) => value ? new Date(value).toLocaleString([], { month: 'short', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : 'Never';
const fmtFullDate = (value?: string | null) => value ? new Date(value).toLocaleString([], { month: 'short', day: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '—';
const initials = (u?: Partial<User> | null) => u?.initials || `${u?.firstName?.[0] || ''}${u?.lastName?.[0] || ''}` || '??';

function Logo({ light = false }: { light?: boolean }) {
  return <div className={`flex items-center gap-2.5 ${light ? 'text-white' : 'text-[hsl(var(--foreground))]'}`}>
    <div className="grid h-8 w-8 place-items-center rounded-md bg-[hsl(var(--primary))] text-white"><ShieldCheck size={18} strokeWidth={2.6} /></div>
    <div><div className="font-bold tracking-tight">SMART IAM</div><div className={`eyebrow ${light ? 'text-slate-400' : ''}`}>security console</div></div>
  </div>;
}

function StatusTag({ value, tone }: { value: string; tone?: 'teal' | 'amber' | 'red' | 'slate' }) {
  const lower = value.toLowerCase();
  const inferred = tone || (lower.includes('high') || lower.includes('critical') || lower.includes('failed') || lower.includes('locked') ? 'red' : lower.includes('medium') || lower.includes('pending') || lower.includes('warning') ? 'amber' : lower.includes('active') || lower.includes('success') || lower.includes('resolved') || lower.includes('low') ? 'teal' : 'slate');
  return <span className={`tag tag-${inferred}`}>{value}</span>;
}

function Avatar({ user, size = 'md' }: { user?: Partial<User> | null; size?: 'sm' | 'md' }) {
  return <div data-testid={`avatar-${user?.id || 'current'}`} className={`grid shrink-0 place-items-center rounded-full bg-[hsl(174_62%_91%)] font-mono font-bold text-[hsl(174_76%_25%)] ${size === 'sm' ? 'h-7 w-7 text-[10px]' : 'h-9 w-9 text-xs'}`}>{initials(user)}</div>;
}

function Button({ children, className = '', variant = 'primary', ...props }: ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'secondary' | 'danger' | 'quiet' }) {
  return <button className={`btn btn-${variant} ${className}`} {...props}>{children}</button>;
}

function EmptyState({ icon: Icon = CircleHelp, title, text, action }: { icon?: typeof CircleHelp; title: string; text: string; action?: ReactNode }) {
  return <div className="flex min-h-[260px] flex-col items-center justify-center gap-2 p-8 text-center"><div className="mb-2 grid h-11 w-11 place-items-center rounded-full bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]"><Icon size={20} /></div><h3 className="font-bold">{title}</h3><p className="max-w-sm text-sm text-[hsl(var(--muted-foreground))]">{text}</p>{action}</div>;
}

function LoadingRows({ count = 5 }: { count?: number }) {
  return <div className="space-y-3 p-5">{Array.from({ length: count }).map((_, i) => <div key={i} className="skeleton h-11 w-full" />)}</div>;
}

function ErrorState({ retry }: { retry?: () => void }) {
  return <div className="flex min-h-[240px] flex-col items-center justify-center gap-3 p-8 text-center"><AlertTriangle className="text-[hsl(var(--destructive))]" /><p className="font-semibold">The console could not load this view.</p><p className="text-sm text-[hsl(var(--muted-foreground))]">Check the service connection, then try again.</p>{retry && <Button variant="secondary" onClick={retry}><RefreshCw size={14} />Retry</Button>}</div>;
}

function AppShell({ children }: { children: ReactNode }) {
  const [location, setLocation] = useLocation();
  const [open, setOpen] = useState(false);
  const session = useGetAuthSession({ query: { queryKey: getGetAuthSessionQueryKey(), retry: false } });
  const logout = useLogout();
  const user = session.data?.user;
  const doLogout = () => logout.mutate(undefined, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getGetAuthSessionQueryKey() }); setLocation('/'); } });
  return <div className="min-h-[100dvh] bg-[hsl(var(--background))]">
    <aside className={`fixed inset-y-0 left-0 z-30 flex w-[246px] flex-col bg-[hsl(var(--sidebar))] px-3 py-5 text-[hsl(var(--sidebar-foreground))] transition-transform md:translate-x-0 ${open ? 'translate-x-0' : '-translate-x-full'}`}>
      <div className="px-3"><Logo light /></div>
      <div className="mt-9 px-3 eyebrow text-slate-500">workspace</div>
      <nav className="mt-2 space-y-1">{navItems.map(({ href, label, icon: Icon }) => <Link key={href} href={href} data-testid={`link-nav-${label.toLowerCase().replace(/\s/g, '-')}`} onClick={() => setOpen(false)} className={`flex items-center gap-3 rounded-md px-3 py-2.5 text-sm font-semibold transition-colors ${location === href ? 'bg-[hsl(var(--sidebar-accent))] text-white' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}><Icon size={17} /><span>{label}</span>{href === '/alerts' && <span className="ml-auto rounded bg-[hsl(var(--accent))] px-1.5 py-0.5 font-mono text-[10px] text-slate-900">3</span>}</Link>)}</nav>
      <div className="mt-auto space-y-1 border-t border-slate-700/70 pt-4">
        <Link href="/profile" className="flex items-center gap-3 rounded-md px-3 py-2.5 text-sm font-semibold text-slate-400 hover:bg-slate-800 hover:text-white"><UserRound size={17} />Profile</Link>
        <Link href="/settings" className="flex items-center gap-3 rounded-md px-3 py-2.5 text-sm font-semibold text-slate-400 hover:bg-slate-800 hover:text-white"><Settings2 size={17} />Settings</Link>
        <button data-testid="button-sign-out" onClick={doLogout} className="flex w-full items-center gap-3 rounded-md px-3 py-2.5 text-left text-sm font-semibold text-slate-400 hover:bg-slate-800 hover:text-white"><LogOut size={17} />Sign out</button>
      </div>
    </aside>
    {open && <button aria-label="Close navigation" className="fixed inset-0 z-20 bg-slate-950/40 md:hidden" onClick={() => setOpen(false)} />}
    <div className="md:pl-[246px]">
      <header className="sticky top-0 z-10 flex h-16 items-center justify-between border-b border-[hsl(var(--border))] bg-[hsl(var(--background)/.93)] px-5 backdrop-blur md:px-8">
        <div className="flex items-center gap-3"><button aria-label="Open navigation" className="btn btn-quiet p-2 md:hidden" onClick={() => setOpen(true)}><Menu size={19} /></button><div className="eyebrow">tenant / northstar</div></div>
        <div className="flex items-center gap-3"><div className="hidden items-center gap-2 text-xs text-[hsl(var(--muted-foreground))] sm:flex"><span className="h-2 w-2 rounded-full bg-emerald-500" />Systems nominal</div><Link href="/profile" className="flex items-center gap-2 border-l border-[hsl(var(--border))] pl-3"><Avatar user={user} size="sm" /><span className="hidden text-sm font-semibold sm:block">{user?.firstName || 'Security admin'}</span><ChevronDown size={14} className="text-[hsl(var(--muted-foreground))]" /></Link></div>
      </header>
      <main className="shell-grid min-h-[calc(100dvh-64px)] p-4 md:p-8"><div className="page-enter mx-auto max-w-[1440px]">{children}</div></main>
    </div>
  </div>;
}

function PageHeader({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><div className="eyebrow mb-2 text-[hsl(var(--primary))]">{eyebrow}</div><h1 className="text-2xl font-bold tracking-tight md:text-3xl">{title}</h1>{description && <p className="mt-1.5 text-sm text-[hsl(var(--muted-foreground))]">{description}</p>}</div>{action}</div>;
}

function PublicFrame({ children }: { children: ReactNode }) {
  return <div className="min-h-[100dvh] bg-[hsl(var(--sidebar))] text-white"><header className="flex items-center justify-between px-6 py-5 md:px-12"><Logo light /><Link href="/login" className="text-sm font-semibold text-slate-300 hover:text-white">Sign in <ArrowRight className="ml-1 inline" size={14} /></Link></header>{children}</div>;
}

function Home() {
  const health = useHealthCheck({ query: { queryKey: getHealthCheckQueryKey(), retry: false } });
  return <PublicFrame><div className="mx-auto grid max-w-7xl items-center gap-16 px-6 pb-20 pt-16 md:grid-cols-[1.1fr_.9fr] md:px-12 md:pt-24"><div><div className="eyebrow mb-5 text-[hsl(var(--accent))]">identity control plane / v2.6</div><h1 className="max-w-2xl text-5xl font-bold tracking-[-.04em] md:text-7xl">Trust is a <span className="text-[hsl(var(--accent))]">live signal.</span></h1><p className="mt-7 max-w-xl text-lg leading-8 text-slate-400">Smart IAM gives security teams one sharp view of every identity, permission, and authentication decision across the organization.</p><div className="mt-9 flex flex-wrap gap-3"><Link href="/login" className="btn btn-primary" data-testid="link-home-login">Enter console <ArrowRight size={16} /></Link><Link href="/register" className="btn border border-slate-600 text-slate-200 hover:bg-slate-800" data-testid="link-home-register">Create workspace</Link></div><div className="mt-10 flex items-center gap-3 text-xs text-slate-500"><span className={`h-2 w-2 rounded-full ${health.isError ? 'bg-amber-400' : 'bg-emerald-400'}`} />{health.isError ? 'Control plane awaiting connection' : 'Control plane operational'}<span className="ml-2 font-mono">uptime / live</span></div></div><div className="relative"><div className="absolute -inset-8 rounded-full bg-[hsl(174_76%_31%/.13)] blur-3xl" /><div className="relative rounded-xl border border-slate-700 bg-slate-900/80 p-5 shadow-2xl"><div className="mb-5 flex items-center justify-between border-b border-slate-700 pb-4"><div className="eyebrow text-slate-500">live access posture</div><span className="tag tag-teal">protected</span></div><div className="grid grid-cols-2 gap-3">{[['Identities', '2,481', '↑ 8.2%'], ['Risk score', '18.4', 'low'], ['Open alerts', '03', 'review'], ['Sessions', '412', 'active']].map(([label, value, sub]) => <div key={label} className="rounded-md border border-slate-700 bg-slate-800/70 p-4"><div className="eyebrow text-slate-500">{label}</div><div className="mt-2 text-2xl font-bold">{value}</div><div className="mt-1 text-xs text-slate-400">{sub}</div></div>)}</div><div className="mt-3 rounded-md border border-slate-700 bg-slate-800/70 p-4"><div className="flex items-center justify-between text-xs text-slate-400"><span>identity assurance</span><span className="font-mono text-[hsl(var(--accent))]">92.6%</span></div><div className="mt-3 h-2 overflow-hidden rounded bg-slate-700"><div className="h-full w-[92%] bg-[hsl(var(--accent))]" /></div></div><div className="mt-5 flex items-center gap-3 text-xs text-slate-400"><Activity size={15} className="text-[hsl(var(--accent))]" />Signals evaluated in real time</div></div></div></div><div className="border-t border-slate-800 bg-slate-950/40 px-6 py-7 md:px-12"><div className="mx-auto grid max-w-7xl gap-6 text-sm text-slate-400 md:grid-cols-3"><div><div className="mb-2 font-bold text-white">Make access legible</div>Every decision has a reason, owner, and next action.</div><div><div className="mb-2 font-bold text-white">Reduce blind spots</div>Risk events, alerts, and audit trails share one timeline.</div><div><div className="mb-2 font-bold text-white">Move with confidence</div>Designed for the response room, not the demo room.</div></div></div></PublicFrame>;
}

function AuthCard({ mode }: { mode: 'login' | 'register' }) {
  const [, setLocation] = useLocation();
  const login = useLogin();
  const register = useRegister();
  const verify = useVerifyMfa();
  const [mfa, setMfa] = useState<{ challengeId: string; demoOtp?: string } | null>(null);
  const [form, setForm] = useState<Record<string, string>>({ identifier: '', password: '', firstName: '', lastName: '', username: '', email: '', confirmPassword: '' });
  const [error, setError] = useState('');
  const change = (key: string) => (e: React.ChangeEvent<HTMLInputElement>) => setForm((v) => ({ ...v, [key]: e.target.value }));
  const submit = (e: React.FormEvent) => { e.preventDefault(); setError(''); if (mode === 'login') login.mutate({ data: { identifier: form.identifier, password: form.password } }, { onSuccess: (res) => res.mfaRequired && res.challengeId ? setMfa({ challengeId: res.challengeId, demoOtp: res.demoOtp || undefined }) : setLocation('/dashboard'), onError: () => setError('Credentials were not accepted. Check the identifier and password.') }); else register.mutate({ data: { firstName: form.firstName, lastName: form.lastName, username: form.username, email: form.email, password: form.password, confirmPassword: form.confirmPassword } }, { onSuccess: () => setLocation('/dashboard'), onError: () => setError('Registration could not be completed. Review the details and try again.') }); };
  const submitMfa = (e: React.FormEvent) => { e.preventDefault(); verify.mutate({ data: { challengeId: mfa?.challengeId || '', code: form.code || '' } }, { onSuccess: () => setLocation('/dashboard'), onError: () => setError('That verification code is not valid.') }); };
  return <PublicFrame><div className="mx-auto flex min-h-[calc(100dvh-82px)] max-w-md items-center justify-center px-6 py-12"><div className="w-full rounded-xl border border-slate-700 bg-slate-900 p-7 shadow-2xl"><div className="eyebrow text-[hsl(var(--accent))]">{mfa ? 'step 02 / verify' : mode === 'login' ? 'secure sign in' : 'workspace registration'}</div><h1 className="mt-3 text-2xl font-bold">{mfa ? 'Confirm it is you' : mode === 'login' ? 'Welcome back' : 'Set up your console'}</h1><p className="mt-2 text-sm leading-6 text-slate-400">{mfa ? 'Enter the six-digit code from your authenticator app to finish sign in.' : mode === 'login' ? 'Use your work identity to access the Northstar tenant.' : 'Create an administrator identity for your security workspace.'}</p>{error && <div className="mt-5 rounded-md border border-red-800 bg-red-950/50 p-3 text-sm text-red-300">{error}</div>}<form className="mt-7 space-y-4" onSubmit={mfa ? submitMfa : submit}>{mfa ? <><label className="block text-xs font-semibold text-slate-300">Authentication code<input autoFocus inputMode="numeric" maxLength={6} className="field mt-2 bg-slate-800 text-center font-mono text-lg tracking-[.35em] text-white" data-testid="input-mfa-code" value={form.code || ''} onChange={change('code')} /></label>{mfa.demoOtp && <div className="rounded-md bg-slate-800 p-3 text-center text-xs text-slate-400">Demo code <span className="font-mono font-bold text-[hsl(var(--accent))]">{mfa.demoOtp}</span></div>}</> : mode === 'login' ? <><Field label="Username or email" value={form.identifier} onChange={change('identifier')} testId="input-identifier" /><Field label="Password" type="password" value={form.password} onChange={change('password')} testId="input-password" /><div className="flex items-center justify-between text-xs text-slate-400"><label className="flex items-center gap-2"><input type="checkbox" />Trust this device</label><span>Risk checks enabled</span></div></> : <><div className="grid gap-4 sm:grid-cols-2"><Field label="First name" value={form.firstName} onChange={change('firstName')} testId="input-first-name" /><Field label="Last name" value={form.lastName} onChange={change('lastName')} testId="input-last-name" /></div><Field label="Username" value={form.username} onChange={change('username')} testId="input-username" /><Field label="Work email" type="email" value={form.email} onChange={change('email')} testId="input-email" /><Field label="Password" type="password" value={form.password} onChange={change('password')} testId="input-password" /><Field label="Confirm password" type="password" value={form.confirmPassword} onChange={change('confirmPassword')} testId="input-confirm-password" /></>}<Button type="submit" className="mt-2 w-full" disabled={login.isPending || register.isPending || verify.isPending}>{mfa ? 'Verify and continue' : mode === 'login' ? 'Sign in securely' : 'Create administrator' }<ArrowRight size={15} /></Button></form><div className="mt-6 border-t border-slate-700 pt-5 text-center text-sm text-slate-400">{mode === 'login' ? <>New to Smart IAM? <Link href="/register" className="font-semibold text-[hsl(var(--accent))]">Create an account</Link></> : <>Already have access? <Link href="/login" className="font-semibold text-[hsl(var(--accent))]">Sign in</Link></>}</div></div></div></PublicFrame>;
}

function Field({ label, value, onChange, type = 'text', testId }: { label: string; value: string; onChange: (e: ChangeEvent<HTMLInputElement>) => void; type?: string; testId: string }) {
  return <label className="block text-xs font-semibold text-slate-300">{label}<input className="field mt-2 bg-slate-800 text-white placeholder:text-slate-600" type={type} value={value} onChange={onChange} data-testid={testId} /></label>;
}

function Dashboard() {
  const stats = useGetDashboardStats({ query: { queryKey: getGetDashboardStatsQueryKey() } });
  const charts = useGetDashboardCharts({ query: { queryKey: getGetDashboardChartsQueryKey() } });
  const alerts = useListAlerts({ status: 'open', page: 1, pageSize: 4 }, { query: { queryKey: getListAlertsQueryKey({ status: 'open', page: 1, pageSize: 4 }) } });
  const audit = useListAuditLogs({ page: 1, pageSize: 5 }, { query: { queryKey: getListAuditLogsQueryKey({ page: 1, pageSize: 5 }) } });
  const s = stats.data;
  const c = charts.data;
  const metricItems: Array<[string, string, string | number, LucideIcon]> = [['totalUsers', 'IDENTITIES', s?.totalUsers ?? '—', UsersRound], ['activeUsers', 'ACTIVE USERS', s?.activeUsers ?? '—', Activity], ['openAlerts', 'OPEN ALERTS', s?.openAlerts ?? '—', AlertTriangle], ['riskScore', 'RISK SCORE', s?.riskScore ?? '—', Shield]];
  return <><PageHeader eyebrow="overview / system posture" title="Good morning, security team." description="A concise view of identity health, access risk, and the decisions that need attention." action={<Button variant="secondary" onClick={() => { stats.refetch(); charts.refetch(); }}><RefreshCw size={14} />Refresh view</Button>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{metricItems.map(([key, label, value, Icon]) => <div className="panel p-5" key={key as string}><div className="flex items-center justify-between"><div className="eyebrow">{label as string}</div><Icon size={17} className="text-[hsl(var(--primary))]" /></div><div className="mt-4 text-3xl font-bold tracking-tight">{value as string}</div><div className="mt-2 text-xs text-[hsl(var(--muted-foreground))]">{key === 'riskScore' ? 'lower is safer' : key === 'openAlerts' ? 'requires triage' : 'from current tenant'}</div></div>)}</div><div className="mt-5 grid gap-5 xl:grid-cols-[1.4fr_.9fr]"><div className="panel p-5"><div className="mb-5 flex items-center justify-between"><div><div className="eyebrow">authentication telemetry</div><h2 className="mt-1 text-lg font-bold">Login activity</h2></div><span className="tag tag-teal">last 7 days</span></div><div className="flex h-48 items-end gap-2 border-b border-l border-[hsl(var(--border))] px-3 pb-0 pt-5">{(c?.loginActivity || []).map((point, i) => <div className="flex h-full flex-1 flex-col items-center justify-end gap-2" key={point.label}><div className="w-full max-w-10 rounded-t bg-[hsl(var(--primary))] transition-all" style={{ height: `${Math.max(8, Math.min(100, point.value / Math.max(...(c?.loginActivity || [{ value: 1 }]).map((p) => p.value)) * 100))}%` }} title={`${point.value} successful`} /><div className="font-mono text-[9px] text-[hsl(var(--muted-foreground))]">{point.label}</div></div>)}{!c && <div className="skeleton h-full w-full" />}</div></div><div className="panel p-5"><div className="eyebrow">current exposure</div><h2 className="mt-1 text-lg font-bold">Risk distribution</h2><div className="mt-6 space-y-4">{(c?.riskDistribution || []).map((point) => <div key={point.label}><div className="mb-1 flex justify-between text-xs"><span>{point.label}</span><span className="font-mono font-bold">{point.value}</span></div><div className="h-2 rounded bg-[hsl(var(--secondary))]"><div className={`h-full rounded ${point.label.toLowerCase().includes('high') ? 'bg-[hsl(var(--destructive))]' : point.label.toLowerCase().includes('medium') ? 'bg-[hsl(var(--accent))]' : 'bg-[hsl(var(--primary))]'}`} style={{ width: `${Math.min(100, point.value)}%` }} /></div></div>)}</div></div></div><div className="mt-5 grid gap-5 xl:grid-cols-2"><div className="panel"><div className="flex items-center justify-between border-b border-[hsl(var(--border))] p-5"><div><div className="eyebrow">needs attention</div><h2 className="mt-1 text-lg font-bold">Open alerts</h2></div><Link href="/alerts" className="text-xs font-bold text-[hsl(var(--primary))]">View queue <ArrowRight className="ml-1 inline" size={13} /></Link></div>{alerts.isLoading ? <LoadingRows count={3} /> : alerts.isError ? <ErrorState retry={() => alerts.refetch()} /> : !alerts.data?.items.length ? <EmptyState icon={ShieldCheck} title="No open alerts" text="The queue is clear. New anomalies will appear here." /> : <div className="divide-y divide-[hsl(var(--border))]">{alerts.data.items.map((a) => <div className="flex items-center justify-between gap-3 p-4" key={a.id}><div className="min-w-0"><div className="truncate text-sm font-semibold">{a.message}</div><div className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{a.user} · {fmtDate(a.createdAt)}</div></div><StatusTag value={a.severity} /></div>)}</div>}</div><div className="panel"><div className="flex items-center justify-between border-b border-[hsl(var(--border))] p-5"><div><div className="eyebrow">control history</div><h2 className="mt-1 text-lg font-bold">Recent audit activity</h2></div><Link href="/audit" className="text-xs font-bold text-[hsl(var(--primary))]">Full trail <ArrowRight className="ml-1 inline" size={13} /></Link></div>{audit.isLoading ? <LoadingRows count={3} /> : <div className="divide-y divide-[hsl(var(--border))]">{(audit.data?.items || []).map((l) => <div key={l.id} className="flex items-start gap-3 p-4"><div className="mt-1 h-2 w-2 shrink-0 rounded-full bg-[hsl(var(--primary))]" /><div className="min-w-0"><div className="text-sm font-semibold">{l.action} <span className="font-normal text-[hsl(var(--muted-foreground))]">on {l.resource}</span></div><div className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{l.user} · {fmtDate(l.timestamp)}</div></div></div>)}</div>}</div></div></>;
}

function UsersPage() {
  const [search, setSearch] = useState(''); const [status, setStatus] = useState(''); const [page, setPage] = useState(1); const [modal, setModal] = useState(false); const [selectedUserId, setSelectedUserId] = useState<number | null>(null); const [form, setForm] = useState({ username: '', email: '', firstName: '', lastName: '', password: '' });
  const params = useMemo(() => ({ search: search || undefined, status: status || undefined, page, pageSize: 10 }), [search, status, page]);
  const q = useListUsers(params, { query: { queryKey: getListUsersQueryKey(params) } }); const selectedUser = useGetUser(selectedUserId || 0, { query: { enabled: selectedUserId !== null, queryKey: getGetUserQueryKey(selectedUserId || 0) } }); const create = useCreateUser(); const update = useUpdateUser(); const remove = useDeleteUser();
  const refresh = () => queryClient.invalidateQueries({ queryKey: getListUsersQueryKey(params) });
  const submit = (e: React.FormEvent) => { e.preventDefault(); create.mutate({ data: { ...form, roleIds: [] } }, { onSuccess: () => { setModal(false); setForm({ username: '', email: '', firstName: '', lastName: '', password: '' }); refresh(); } }); };
  const users = q.data?.items || [];
  return <><PageHeader eyebrow="directory / identities" title="Users" description={`${q.data?.total ?? 0} identities in this tenant.`} action={<Button onClick={() => setModal(true)}><Plus size={15} />Add user</Button>} /><div className="panel overflow-hidden"><div className="flex flex-col gap-3 border-b border-[hsl(var(--border))] p-4 md:flex-row"><div className="relative flex-1"><Search size={15} className="absolute left-3 top-2.5 text-[hsl(var(--muted-foreground))]" /><input className="field pl-9" placeholder="Search name, email, username" data-testid="input-search-users" value={search} onChange={(e) => { setPage(1); setSearch(e.target.value); }} /></div><select className="field md:w-40" value={status} onChange={(e) => { setPage(1); setStatus(e.target.value); }} data-testid="select-user-status"><option value="">All status</option><option value="active">Active</option><option value="locked">Locked</option><option value="inactive">Inactive</option></select></div>{q.isLoading ? <LoadingRows /> : q.isError ? <ErrorState retry={() => q.refetch()} /> : users.length === 0 ? <EmptyState icon={UsersRound} title="No identities found" text="Adjust your filters or add the first user to this tenant." action={<Button onClick={() => setModal(true)}><Plus size={14} />Add user</Button>} /> : <div className="mobile-scroll"><table className="w-full min-w-[760px] text-left text-sm"><thead className="bg-[hsl(var(--secondary)/.55)] text-[10px] uppercase tracking-[.12em] text-[hsl(var(--muted-foreground))]"><tr><th className="px-5 py-3">Identity</th><th className="px-4 py-3">Access</th><th className="px-4 py-3">MFA</th><th className="px-4 py-3">Last login</th><th className="px-4 py-3 text-right">Actions</th></tr></thead><tbody className="divide-y divide-[hsl(var(--border))]">{users.map((u) => <tr key={u.id} data-testid={`row-user-${u.id}`}><td className="px-5 py-4"><div className="flex items-center gap-3"><Avatar user={u} /><div><div className="font-semibold">{u.firstName} {u.lastName}</div><div className="text-xs text-[hsl(var(--muted-foreground))]">{u.email} · @{u.username}</div></div></div></td><td className="px-4 py-4"><div className="flex flex-wrap gap-1">{u.roles.slice(0, 2).map((r) => <StatusTag key={r.id} value={r.name} tone="slate" />)}</div><div className="mt-1"><StatusTag value={u.isLocked ? 'Locked' : u.isActive ? 'Active' : 'Inactive'} /></div></td><td className="px-4 py-4">{u.mfaEnabled ? <span className="flex items-center gap-1 text-xs font-semibold text-[hsl(var(--primary))]"><Fingerprint size={14} />Enabled</span> : <span className="text-xs text-[hsl(var(--muted-foreground))]">Not enrolled</span>}</td><td className="px-4 py-4 text-xs text-[hsl(var(--muted-foreground))]">{fmtDate(u.lastLogin)}</td><td className="px-4 py-4 text-right"><Button variant="quiet" title="Inspect user" onClick={() => setSelectedUserId(u.id)}><ExternalLink size={15} /></Button><Button variant="quiet" title="Lock or unlock" onClick={() => update.mutate({ id: u.id, data: { isLocked: !u.isLocked } }, { onSuccess: refresh })}><LockKeyhole size={15} /></Button><Button variant="quiet" title="Delete user" onClick={() => { if (window.confirm(`Delete ${u.firstName} ${u.lastName}?`)) remove.mutate({ id: u.id }, { onSuccess: refresh }); }}><Trash2 size={15} /></Button></td></tr>)}</tbody></table></div>}<Pagination page={q.data?.page || page} total={q.data?.total || 0} pageSize={q.data?.pageSize || 10} onPage={setPage} /></div>{modal && <Modal title="Add identity" onClose={() => setModal(false)}><form className="space-y-4" onSubmit={submit}>{[['firstName', 'First name'], ['lastName', 'Last name'], ['username', 'Username'], ['email', 'Work email'], ['password', 'Temporary password']].map(([key, label]) => <label className="block text-xs font-semibold" key={key}>{label}<input className="field mt-2" type={key === 'password' ? 'password' : key === 'email' ? 'email' : 'text'} required value={form[key as keyof typeof form]} onChange={(e) => setForm({ ...form, [key]: e.target.value })} /></label>)}<Button className="w-full" disabled={create.isPending}>{create.isPending ? 'Creating…' : 'Create identity'}</Button></form></Modal>}{selectedUserId !== null && <Modal title="Identity detail" onClose={() => setSelectedUserId(null)}>{selectedUser.isLoading ? <LoadingRows count={3} /> : selectedUser.data ? <div className="space-y-4"><div className="flex items-center gap-3"><Avatar user={selectedUser.data} /><div><div className="font-bold">{selectedUser.data.firstName} {selectedUser.data.lastName}</div><div className="text-sm text-[hsl(var(--muted-foreground))]">{selectedUser.data.email}</div></div></div><div className="grid grid-cols-2 gap-3 text-sm"><div className="rounded bg-[hsl(var(--secondary))] p-3"><div className="eyebrow">username</div><div className="mt-1 font-mono">@{selectedUser.data.username}</div></div><div className="rounded bg-[hsl(var(--secondary))] p-3"><div className="eyebrow">created</div><div className="mt-1">{fmtDate(selectedUser.data.createdAt)}</div></div></div><div className="flex gap-2">{selectedUser.data.roles.map((r) => <StatusTag key={r.id} value={r.name} />)}</div></div> : <ErrorState retry={() => selectedUser.refetch()} />}</Modal>}</>;
}

function Pagination({ page, total, pageSize, onPage }: { page: number; total: number; pageSize: number; onPage: (n: number) => void }) {
  const pages = Math.max(1, Math.ceil(total / pageSize)); return <div className="flex items-center justify-between border-t border-[hsl(var(--border))] px-5 py-3 text-xs text-[hsl(var(--muted-foreground))]"><span>Showing {total ? (page - 1) * pageSize + 1 : 0}–{Math.min(page * pageSize, total)} of {total}</span><div className="flex gap-1"><Button variant="secondary" className="p-2" disabled={page <= 1} onClick={() => onPage(page - 1)}><ChevronLeft size={14} /></Button><span className="grid min-w-8 place-items-center font-mono">{page}/{pages}</span><Button variant="secondary" className="p-2" disabled={page >= pages} onClick={() => onPage(page + 1)}><ChevronRight size={14} /></Button></div></div>;
}

function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: ReactNode }) {
  return <div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/45 p-4"><div className="w-full max-w-lg rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6 shadow-2xl"><div className="mb-5 flex items-center justify-between"><h2 className="text-lg font-bold">{title}</h2><button className="btn btn-quiet p-1.5" onClick={onClose}><X size={17} /></button></div>{children}</div></div>;
}

function RolesPage() {
  const q = useListRoles({ query: { queryKey: getListRolesQueryKey() } }); const perms = useListPermissions({ query: { queryKey: getListPermissionsQueryKey() } }); const create = useCreateRole(); const update = useUpdateRole(); const remove = useDeleteRole(); const assign = useAssignRolePermissions(); const [modal, setModal] = useState(false); const [selected, setSelected] = useState<Role | null>(null); const [form, setForm] = useState({ name: '', description: '' });
  const submit = (e: React.FormEvent) => { e.preventDefault(); if (selected) update.mutate({ id: selected.id, data: form }, { onSuccess: () => { setModal(false); queryClient.invalidateQueries({ queryKey: getListRolesQueryKey() }); } }); else create.mutate({ data: form }, { onSuccess: () => { setModal(false); queryClient.invalidateQueries({ queryKey: getListRolesQueryKey() }); } }); };
  return <><PageHeader eyebrow="access model / roles" title="Roles" description="Bundle permissions into clear, reviewable access profiles." action={<Button onClick={() => { setSelected(null); setForm({ name: '', description: '' }); setModal(true); }}><Plus size={15} />Create role</Button>} /><div className="grid gap-4 lg:grid-cols-2">{q.isLoading ? <LoadingRows count={4} /> : (q.data || []).map((r) => <div className="panel p-5" key={r.id}><div className="flex items-start justify-between gap-3"><div><div className="flex items-center gap-2"><h2 className="font-bold">{r.name}</h2><StatusTag value={`${r.userCount} users`} tone="slate" /></div><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">{r.description}</p></div><button className="btn btn-quiet p-1.5" onClick={() => { setSelected(r); setForm({ name: r.name, description: r.description }); setModal(true); }}><MoreHorizontal size={17} /></button></div><div className="mt-5 flex items-center justify-between border-t border-[hsl(var(--border))] pt-4 text-xs text-[hsl(var(--muted-foreground))]"><span className="font-mono">{r.permissionIds.length} permissions · created {fmtDate(r.createdAt)}</span><div className="flex gap-1"><Button variant="secondary" onClick={() => { const ids = perms.data?.filter((p) => r.permissionIds.includes(p.id)).map((p) => p.id) || []; assign.mutate({ id: r.id, data: { permissionIds: ids } }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListRolesQueryKey() }) }); }}><SlidersHorizontal size={14} />Sync permissions</Button><Button variant="quiet" onClick={() => { if (window.confirm(`Delete ${r.name}?`)) remove.mutate({ id: r.id }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListRolesQueryKey() }) }); }}><Trash2 size={14} /></Button></div></div></div>)}{!q.isLoading && !q.data?.length && <div className="panel lg:col-span-2"><EmptyState icon={KeyRound} title="No roles yet" text="Create a role to start shaping least-privilege access." /></div>}</div>{modal && <Modal title={selected ? 'Edit role' : 'Create role'} onClose={() => setModal(false)}><form className="space-y-4" onSubmit={submit}><label className="block text-xs font-semibold">Role name<input className="field mt-2" required value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></label><label className="block text-xs font-semibold">Description<textarea className="field mt-2 min-h-24" value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} /></label><Button className="w-full">Save role</Button></form></Modal>}</>;
}

function PermissionsPage() {
  const q = useListPermissions({ query: { queryKey: getListPermissionsQueryKey() } }); const grouped = useMemo(() => (q.data || []).reduce<Record<string, Permission[]>>((acc, p) => { (acc[p.resource] ||= []).push(p); return acc; }, {}), [q.data]);
  return <><PageHeader eyebrow="access model / catalog" title="Permissions" description="The atomic actions available to every role in this workspace." /><div className="grid gap-5 xl:grid-cols-2">{q.isLoading ? <LoadingRows count={5} /> : Object.entries(grouped).map(([resource, items]) => <div className="panel overflow-hidden" key={resource}><div className="border-b border-[hsl(var(--border))] bg-[hsl(var(--secondary)/.5)] px-5 py-4"><div className="eyebrow">resource</div><h2 className="mt-1 font-bold">{resource}</h2></div><div className="divide-y divide-[hsl(var(--border))]">{items.map((p) => <div className="flex items-center justify-between gap-4 px-5 py-4" key={p.id}><div><div className="text-sm font-semibold">{p.name}</div><div className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{p.description}</div></div><StatusTag value={p.action} tone="slate" /></div>)}</div></div>)}{!q.isLoading && !q.data?.length && <div className="panel xl:col-span-2"><EmptyState icon={FileKey2} title="No permissions defined" text="Permission catalog is empty for this tenant." /></div>}</div></>;
}

function SecurityPage() {
  const [search, setSearch] = useState(''); const [riskLevel, setRiskLevel] = useState(''); const [page, setPage] = useState(1); const [result, setResult] = useState<SecurityEvent | null>(null); const [eventType, setEventType] = useState('impossible_travel');
  const params = useMemo(() => ({ search: search || undefined, riskLevel: riskLevel || undefined, page, pageSize: 10 }), [search, riskLevel, page]); const q = useListSecurityEvents(params, { query: { queryKey: getListSecurityEventsQueryKey(params) } }); const simulate = useSimulateSecurityEvent();
  return <><PageHeader eyebrow="security / detections" title="Security events" description="Inspect authentication decisions and safely test your detection pipeline." action={<Button variant="secondary" onClick={() => q.refetch()}><RefreshCw size={14} />Refresh signals</Button>} /><div className="mb-5 grid gap-5 xl:grid-cols-[1fr_360px]"><div className="panel p-5"><div className="eyebrow">event simulator</div><h2 className="mt-1 text-lg font-bold">Generate a safe test signal</h2><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">Synthetic events are marked for review and never modify identity state.</p><div className="mt-5 flex flex-col gap-3 sm:flex-row"><select className="field" value={eventType} onChange={(e) => setEventType(e.target.value)}><option value="impossible_travel">Impossible travel</option><option value="credential_stuffing">Credential stuffing</option><option value="new_device">New device</option><option value="suspicious_ip">Suspicious IP</option></select><Button onClick={() => simulate.mutate({ data: { eventType } }, { onSuccess: (data) => setResult(data.event), onError: () => setResult(null) })} disabled={simulate.isPending}><Zap size={14} />{simulate.isPending ? 'Simulating…' : 'Run simulation'}</Button></div>{result && <div className="mt-4 rounded-md border border-[hsl(var(--primary)/.3)] bg-[hsl(174_62%_95%)] p-4 text-sm"><div className="flex items-center gap-2 font-bold text-[hsl(var(--primary))]"><Check size={15} />Signal recorded</div><div className="mt-2 text-xs text-[hsl(var(--muted-foreground))]">{result.reason} · risk score {result.riskScore}</div></div>}</div><div className="panel border-[hsl(var(--accent)/.5)] p-5"><div className="eyebrow text-[hsl(28_76%_34%)]">operator note</div><p className="mt-2 text-sm leading-6">Use simulation before shipping rule changes. It exercises scoring, alert creation, and audit capture without touching real access.</p></div></div><div className="panel overflow-hidden"><div className="flex flex-col gap-3 border-b border-[hsl(var(--border))] p-4 md:flex-row"><div className="relative flex-1"><Search size={15} className="absolute left-3 top-2.5 text-[hsl(var(--muted-foreground))]" /><input className="field pl-9" placeholder="Search user, IP, reason" value={search} onChange={(e) => { setPage(1); setSearch(e.target.value); }} /></div><select className="field md:w-36" value={riskLevel} onChange={(e) => { setPage(1); setRiskLevel(e.target.value); }}><option value="">All risk</option><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option></select></div>{q.isLoading ? <LoadingRows /> : q.isError ? <ErrorState retry={() => q.refetch()} /> : !q.data?.items.length ? <EmptyState icon={Shield} title="No risk events" text="No authentication signals match the current filters." /> : <div className="mobile-scroll"><table className="w-full min-w-[820px] text-left text-sm"><thead className="bg-[hsl(var(--secondary)/.55)] text-[10px] uppercase tracking-[.12em] text-[hsl(var(--muted-foreground))]"><tr><th className="px-5 py-3">Signal</th><th className="px-4 py-3">Network</th><th className="px-4 py-3">Decision</th><th className="px-4 py-3">Risk</th><th className="px-4 py-3">Observed</th></tr></thead><tbody className="divide-y divide-[hsl(var(--border))]">{q.data.items.map((e) => <tr key={e.id}><td className="px-5 py-4"><div className="font-semibold">{e.user}</div><div className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{e.reason}</div></td><td className="px-4 py-4"><div className="mono text-xs">{e.ipAddress}</div><div className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{e.device}</div></td><td className="px-4 py-4"><StatusTag value={e.success ? 'Success' : 'Blocked'} /></td><td className="px-4 py-4"><StatusTag value={`${e.riskLevel} · ${e.riskScore}`} /></td><td className="px-4 py-4 text-xs text-[hsl(var(--muted-foreground))]">{fmtFullDate(e.timestamp)}</td></tr>)}</tbody></table></div>}<Pagination page={q.data?.page || page} total={q.data?.total || 0} pageSize={q.data?.pageSize || 10} onPage={setPage} /></div></>;
}

function AlertsPage() {
  const [severity, setSeverity] = useState(''); const [status, setStatus] = useState('open'); const [page, setPage] = useState(1); const params = useMemo(() => ({ severity: severity || undefined, status: status || undefined, page, pageSize: 10 }), [severity, status, page]); const q = useListAlerts(params, { query: { queryKey: getListAlertsQueryKey(params) } }); const resolve = useResolveAlert(); const refresh = () => queryClient.invalidateQueries({ queryKey: getListAlertsQueryKey(params) });
  return <><PageHeader eyebrow="response / queue" title="Alert queue" description="Triage anomalous activity and close the loop on the signals behind it." action={<Button variant="secondary" onClick={() => q.refetch()}><RefreshCw size={14} />Refresh queue</Button>} /><div className="panel overflow-hidden"><div className="flex flex-col gap-3 border-b border-[hsl(var(--border))] p-4 md:flex-row"><select className="field md:w-40" value={status} onChange={(e) => { setPage(1); setStatus(e.target.value); }}><option value="">All statuses</option><option value="open">Open</option><option value="resolved">Resolved</option></select><select className="field md:w-40" value={severity} onChange={(e) => { setPage(1); setSeverity(e.target.value); }}><option value="">All severity</option><option value="critical">Critical</option><option value="high">High</option><option value="medium">Medium</option><option value="low">Low</option></select><div className="ml-auto flex items-center gap-2 text-xs text-[hsl(var(--muted-foreground))]"><SlidersHorizontal size={14} />{q.data?.total || 0} events</div></div>{q.isLoading ? <LoadingRows /> : !q.data?.items.length ? <EmptyState icon={AlertTriangle} title="Queue is clear" text="No alerts match the current filters." /> : <div className="divide-y divide-[hsl(var(--border))]">{q.data.items.map((a) => <div className="flex flex-col gap-4 p-5 md:flex-row md:items-center" key={a.id}><div className="grid h-10 w-10 shrink-0 place-items-center rounded-md bg-[hsl(2_88%_93%)] text-[hsl(var(--destructive))]"><AlertTriangle size={18} /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><span className="font-bold">{a.alertType}</span><StatusTag value={a.severity} /><StatusTag value={a.status} /></div><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">{a.message}</p><div className="mt-2 text-xs text-[hsl(var(--muted-foreground))]">{a.user} · score {a.riskScore} · {fmtFullDate(a.createdAt)}</div></div>{a.status.toLowerCase() !== 'resolved' && <Button variant="secondary" onClick={() => resolve.mutate({ id: a.id }, { onSuccess: refresh })} disabled={resolve.isPending}><Check size={14} />Resolve</Button>}</div>)}</div>}<Pagination page={q.data?.page || page} total={q.data?.total || 0} pageSize={q.data?.pageSize || 10} onPage={setPage} /></div></>;
}

function AuditPage() {
  const [search, setSearch] = useState(''); const [action, setAction] = useState(''); const [status, setStatus] = useState(''); const [page, setPage] = useState(1); const params = useMemo(() => ({ search: search || undefined, action: action || undefined, status: status || undefined, page, pageSize: 15 }), [search, action, status, page]); const q = useListAuditLogs(params, { query: { queryKey: getListAuditLogsQueryKey(params) } }); const exportQuery = useExportAuditLogs({ query: { queryKey: getExportAuditLogsQueryKey(), enabled: false } });
  const exportCsv = async () => { const res = await exportQuery.refetch(); if (res.data) { const blob = new Blob([res.data], { type: 'text/csv' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'smart-iam-audit.csv'; a.click(); URL.revokeObjectURL(url); } };
  return <><PageHeader eyebrow="governance / evidence" title="Audit trail" description="Every meaningful access decision, mutation, and operator action." action={<Button variant="secondary" onClick={exportCsv} disabled={exportQuery.isFetching}><Download size={14} />{exportQuery.isFetching ? 'Preparing…' : 'Export CSV'}</Button>} /><div className="panel overflow-hidden"><div className="flex flex-col gap-3 border-b border-[hsl(var(--border))] p-4 md:flex-row"><div className="relative flex-1"><Search size={15} className="absolute left-3 top-2.5 text-[hsl(var(--muted-foreground))]" /><input className="field pl-9" placeholder="Search actor, resource, detail" value={search} onChange={(e) => { setPage(1); setSearch(e.target.value); }} /></div><input className="field md:w-44" placeholder="Action" value={action} onChange={(e) => setAction(e.target.value)} /><select className="field md:w-36" value={status} onChange={(e) => setStatus(e.target.value)}><option value="">All status</option><option value="success">Success</option><option value="failed">Failed</option></select></div>{q.isLoading ? <LoadingRows /> : !q.data?.items.length ? <EmptyState icon={ClipboardList} title="No audit records" text="Try changing the filters to inspect a wider window." /> : <div className="mobile-scroll"><table className="w-full min-w-[900px] text-left text-sm"><thead className="bg-[hsl(var(--secondary)/.55)] text-[10px] uppercase tracking-[.12em] text-[hsl(var(--muted-foreground))]"><tr><th className="px-5 py-3">Time</th><th className="px-4 py-3">Actor</th><th className="px-4 py-3">Action</th><th className="px-4 py-3">Resource</th><th className="px-4 py-3">Result</th><th className="px-4 py-3">Source</th></tr></thead><tbody className="divide-y divide-[hsl(var(--border))]">{q.data.items.map((l) => <tr key={l.id}><td className="px-5 py-4 text-xs text-[hsl(var(--muted-foreground))]">{fmtFullDate(l.timestamp)}</td><td className="px-4 py-4 font-semibold">{l.user}</td><td className="px-4 py-4">{l.action}<div className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{l.details}</div></td><td className="px-4 py-4 mono text-xs">{l.resource}</td><td className="px-4 py-4"><StatusTag value={l.status} /></td><td className="px-4 py-4 mono text-xs text-[hsl(var(--muted-foreground))]">{l.ipAddress}</td></tr>)}</tbody></table></div>}<Pagination page={q.data?.page || page} total={q.data?.total || 0} pageSize={q.data?.pageSize || 15} onPage={setPage} /></div></>;
}

function ProfilePage() {
  const q = useGetProfile({ query: { queryKey: getGetProfileQueryKey() } }); const sessions = useListSessions({ query: { queryKey: getListSessionsQueryKey() } }); const update = useUpdateProfile(); const revoke = useRevokeSession(); const [editing, setEditing] = useState(false); const [form, setForm] = useState({ firstName: '', lastName: '', email: '' });
  const user = q.data; const begin = () => { setForm({ firstName: user?.firstName || '', lastName: user?.lastName || '', email: user?.email || '' }); setEditing(true); }; const save = (e: React.FormEvent) => { e.preventDefault(); update.mutate({ data: form }, { onSuccess: () => { setEditing(false); queryClient.invalidateQueries({ queryKey: getGetProfileQueryKey() }); } }); };
  return <><PageHeader eyebrow="identity / operator" title="Profile" description="Your administrator identity, assurance controls, and active sessions." action={<Button variant="secondary" onClick={begin}><Settings2 size={14} />Edit profile</Button>} /><div className="grid gap-5 xl:grid-cols-[.85fr_1.15fr]"><div className="space-y-5"><div className="panel p-6"><div className="flex items-center gap-4"><Avatar user={user} size="md" /><div><h2 className="font-bold">{user?.firstName} {user?.lastName}</h2><p className="text-sm text-[hsl(var(--muted-foreground))]">{user?.email}</p><div className="mt-2 flex gap-2"><StatusTag value={user?.isActive ? 'Active' : 'Inactive'} /><StatusTag value={user?.mfaEnabled ? 'MFA enabled' : 'MFA required'} /></div></div></div><div className="mt-6 grid grid-cols-2 gap-4 border-t border-[hsl(var(--border))] pt-5"><div><div className="eyebrow">username</div><div className="mt-1 text-sm font-semibold">@{user?.username || '—'}</div></div><div><div className="eyebrow">member since</div><div className="mt-1 text-sm font-semibold">{fmtDate(user?.createdAt)}</div></div></div></div><div className="panel p-6"><div className="eyebrow">assurance</div><h2 className="mt-1 text-lg font-bold">Multi-factor authentication</h2><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">Require a second factor whenever your risk posture changes.</p><div className="mt-5 flex items-center justify-between rounded-md bg-[hsl(var(--secondary)/.6)] p-3"><div className="flex items-center gap-3"><Fingerprint className="text-[hsl(var(--primary))]" size={18} /><div className="text-sm font-semibold">{user?.mfaEnabled ? 'Authenticator protected' : 'Not enrolled'}</div></div><StatusTag value={user?.mfaEnabled ? 'On' : 'Off'} /></div></div></div><div className="panel"><div className="border-b border-[hsl(var(--border))] p-6"><div className="eyebrow">session control</div><h2 className="mt-1 text-lg font-bold">Active sessions</h2></div>{sessions.isLoading ? <LoadingRows count={3} /> : !sessions.data?.length ? <EmptyState icon={Laptop} title="No active sessions" text="Your current session may still be provisioning." /> : <div className="divide-y divide-[hsl(var(--border))]">{sessions.data.map((s: Session) => <div className="flex items-center gap-4 p-5" key={s.id}><div className="grid h-9 w-9 place-items-center rounded-md bg-[hsl(var(--secondary))]"><Laptop size={17} /></div><div className="min-w-0 flex-1"><div className="font-semibold">{s.device} {s.current && <StatusTag value="Current" />}</div><div className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{s.location} · {s.ipAddress} · active {fmtDate(s.lastActiveAt)}</div></div>{!s.current && <Button variant="secondary" onClick={() => revoke.mutate({ id: s.id }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListSessionsQueryKey() }) })}>Revoke</Button>}</div>)}</div>}</div></div>{editing && <Modal title="Edit profile" onClose={() => setEditing(false)}><form className="space-y-4" onSubmit={save}>{[['firstName', 'First name'], ['lastName', 'Last name'], ['email', 'Email']].map(([key, label]) => <label className="block text-xs font-semibold" key={key}>{label}<input className="field mt-2" value={form[key as keyof typeof form]} onChange={(e) => setForm({ ...form, [key]: e.target.value })} /></label>)}<Button className="w-full">Save profile</Button></form></Modal>}</>;
}

function SettingsPage() {
  const [risk, setRisk] = useState(true); const [sessionTimeout, setSessionTimeout] = useState('30'); const [requireMfa, setRequireMfa] = useState(true);
  return <><PageHeader eyebrow="workspace / policy" title="Settings" description="Tune the security posture and operator session behavior for this tenant." action={<Button onClick={() => window.alert('Settings saved to this browser session.')}><Check size={14} />Save changes</Button>} /><div className="grid gap-5 xl:grid-cols-[1fr_360px]"><div className="panel divide-y divide-[hsl(var(--border))]"><SettingRow icon={Shield} title="Adaptive risk scoring" text="Evaluate device, location, and authentication context on every login." checked={risk} onChange={setRisk} /><SettingRow icon={Fingerprint} title="Require MFA for administrators" text="Block privileged access until a second factor is verified." checked={requireMfa} onChange={setRequireMfa} /><div className="flex items-center justify-between gap-5 p-6"><div className="flex items-start gap-4"><div className="rounded-md bg-[hsl(var(--secondary))] p-2 text-[hsl(var(--primary))]"><Clock3 size={18} /></div><div><div className="font-bold">Idle session timeout</div><div className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">End inactive operator sessions after this interval.</div></div></div><select className="field max-w-28" value={sessionTimeout} onChange={(e) => setSessionTimeout(e.target.value)}><option value="15">15 min</option><option value="30">30 min</option><option value="60">60 min</option><option value="120">2 hr</option></select></div></div><div className="panel bg-[hsl(var(--sidebar))] p-6 text-slate-200"><div className="eyebrow text-[hsl(var(--accent))]">policy posture</div><h2 className="mt-2 text-xl font-bold">Strong by default.</h2><p className="mt-3 text-sm leading-6 text-slate-400">These controls apply tenant-wide. Changes are recorded in the audit trail and take effect for new sessions.</p><div className="mt-7 space-y-4 border-t border-slate-700 pt-5 text-sm"><div className="flex justify-between"><span className="text-slate-400">Risk engine</span><span className="font-mono text-[hsl(var(--accent))]">{risk ? 'ON' : 'OFF'}</span></div><div className="flex justify-between"><span className="text-slate-400">Admin MFA</span><span className="font-mono text-[hsl(var(--accent))]">{requireMfa ? 'REQUIRED' : 'OPTIONAL'}</span></div><div className="flex justify-between"><span className="text-slate-400">Timeout</span><span className="font-mono text-[hsl(var(--accent))]">{sessionTimeout} MIN</span></div></div></div></div></>;
}

function SettingRow({ icon: Icon, title, text, checked, onChange }: { icon: typeof Shield; title: string; text: string; checked: boolean; onChange: (v: boolean) => void }) {
  return <div className="flex items-center justify-between gap-5 p-6"><div className="flex items-start gap-4"><div className="rounded-md bg-[hsl(var(--secondary))] p-2 text-[hsl(var(--primary))]"><Icon size={18} /></div><div><div className="font-bold">{title}</div><div className="mt-1 max-w-xl text-sm text-[hsl(var(--muted-foreground))]">{text}</div></div></div><button className={`relative h-6 w-11 shrink-0 rounded-full transition-colors ${checked ? 'bg-[hsl(var(--primary))]' : 'bg-[hsl(var(--secondary))]'}`} onClick={() => onChange(!checked)} aria-label={title}><span className={`absolute top-1 h-4 w-4 rounded-full bg-white transition-transform ${checked ? 'left-6' : 'left-1'}`} /></button></div>;
}

function Forbidden() { return <div className="grid min-h-[100dvh] place-items-center bg-[hsl(var(--sidebar))] p-6 text-center text-white"><div><div className="mx-auto grid h-14 w-14 place-items-center rounded-xl bg-[hsl(var(--destructive))]"><LockKeyhole /></div><div className="eyebrow mt-7 text-[hsl(var(--accent))]">access denied / 403</div><h1 className="mt-3 text-4xl font-bold">This control is outside your clearance.</h1><p className="mx-auto mt-4 max-w-md text-slate-400">Ask a tenant administrator for the required permission, or return to the overview.</p><Link href="/dashboard" className="btn btn-primary mt-7">Return to overview <ArrowRight size={15} /></Link></div></div>; }

function Router() {
  const publicRoutes = <Switch><Route path="/" component={Home} /><Route path="/login" component={() => <AuthCard mode="login" />} /><Route path="/register" component={() => <AuthCard mode="register" />} /><Route path="/403" component={Forbidden} /><Route component={NotFound} /></Switch>;
  return <Switch><Route path="/dashboard">{() => <AppShell><Dashboard /></AppShell>}</Route><Route path="/users">{() => <AppShell><UsersPage /></AppShell>}</Route><Route path="/roles">{() => <AppShell><RolesPage /></AppShell>}</Route><Route path="/permissions">{() => <AppShell><PermissionsPage /></AppShell>}</Route><Route path="/security">{() => <AppShell><SecurityPage /></AppShell>}</Route><Route path="/alerts">{() => <AppShell><AlertsPage /></AppShell>}</Route><Route path="/audit">{() => <AppShell><AuditPage /></AppShell>}</Route><Route path="/profile">{() => <AppShell><ProfilePage /></AppShell>}</Route><Route path="/settings">{() => <AppShell><SettingsPage /></AppShell>}</Route><Route>{publicRoutes}</Route></Switch>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><ErrorBoundary resetKey={window.location.pathname}><Router /></ErrorBoundary></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;